/* Conheca os Espacos: mapa com trilhas e paginas das atracoes (fotos e videos reais).
   Assume as rotas #espacos e #espaco/<id> das 18 atracoes. Outras rotas seguem como estao. */
const BASE = new URL('./', import.meta.url).href;
const VBASE = new URL('../pnmt-mapa/real/videos/', import.meta.url).href;
const u = p => BASE + p;
const V = n => VBASE + n + '.mp4';
const SITE = {autodromo:'autodromo',motocross:'motocross',kartodromo:'kartodromo',bmx:'bmx',skate:'skate-park',wake:'wake-park',familia:'parque-da-familia',vila:'vila-das-nacoes',roda:'roda-gigante',arvore:'arvore-da-vida',splash:'splash-parque',praca:'praca-de-alimentacao',arena:'arena-show',eventos:'centro-de-eventos',casa:'casa-cuiabana',agroplace:'agroplace',museus:'museus',circo:'circo-do-futuro'};
const BY = Object.fromEntries(Object.entries(SITE).map(([k,v]) => [v,k]));
const CSS = "\n:host{display:block;--bg:#F5F3EE;--paper:#ECE8DF;--ink:#0D2B4D;--ink2:#33475E;--mut:#6B7A8C;--line:#D6DBE1;--lazer:#1E86D0;--esporte:#3E9E36;--cultura:#D9822B;--obra:#C98A0B;--green:#58B947;--gold:#E9B872;\n--d:'Barlow Condensed','Arial Narrow',sans-serif;--t:'Barlow',Arial,sans-serif;color-scheme:light}\n*{box-sizing:border-box}\n[hidden]{display:none!important}\n.root{margin:0;background:var(--bg);color:var(--ink);font-family:var(--t);font-size:17px;line-height:1.6;overflow-x:hidden;-webkit-font-smoothing:antialiased}\n\nbutton{font:inherit;color:inherit;background:none;border:0;cursor:pointer;padding:0}\nimg,video{display:block;max-width:100%}\nh1,h2,h3{font-family:var(--d);font-weight:700;text-transform:uppercase;margin:0;letter-spacing:-.2px}\n.wrap{max-width:1240px;margin:0 auto;padding-left:max(24px,env(safe-area-inset-left,0px));padding-right:max(24px,env(safe-area-inset-right,0px))}\n.eyebrow{font-family:var(--d);font-weight:600;font-size:13.5px;letter-spacing:2.8px;text-transform:uppercase;color:var(--mut)}\n\n/* cabecalho do site (simulado) */\n.site{position:sticky;top:env(safe-area-inset-top,0px);z-index:40;background:var(--ink);color:#fff;border-bottom:3px solid var(--green)}\n.site .wrap{display:flex;align-items:center;gap:30px;height:64px}\n.site b{font-family:var(--d);font-size:19px;letter-spacing:.5px}\n.site nav{display:flex;gap:24px;font-size:14.5px;opacity:.85;overflow:hidden}\n.site nav span.on{color:var(--green);opacity:1}\n\n/* capa */\n.cover{position:relative;height:calc(100svh - 136px);min-height:560px;max-height:900px;overflow:hidden;background:#101d2e;color:#fff}\n.cover video,.cover img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}\n.cover::after{content:\"\";position:absolute;inset:0;background:linear-gradient(180deg,rgba(9,22,40,.45) 0%,rgba(9,22,40,0) 28%,rgba(9,22,40,0) 50%,rgba(9,22,40,.85) 100%)}\n.cover .wrap{position:relative;z-index:1;height:100%;display:flex;flex-direction:column;justify-content:space-between;padding-block:26px 56px}\n.back{align-self:flex-start;display:inline-flex;align-items:center;gap:8px;height:40px;padding:0 16px;border-radius:20px;background:rgba(255,255,255,.14);backdrop-filter:blur(8px);font-size:14px;font-weight:500}\n.back svg{width:12px;height:12px}\n.trail{display:flex;align-items:center;gap:10px;font-size:15px;margin-bottom:14px;flex-wrap:wrap}\n.trail i{width:9px;height:9px;border-radius:50%;background:var(--c)}\n.trail .st{font-size:12.5px;padding:2px 9px;border-radius:2px;background:rgba(255,255,255,.16)}\n.cover h1{font-size:clamp(62px,10vw,156px);line-height:.84}\n.cover .sub{display:flex;justify-content:space-between;align-items:flex-end;gap:24px;margin-top:22px}\n.cover p{margin:0;max-width:440px;font-size:19px;line-height:1.5;color:rgba(255,255,255,.9)}\n.snd{display:flex;align-items:center;gap:10px;font-size:13px;color:rgba(255,255,255,.75)}\n.snd .ln{width:38px;height:1px;background:rgba(255,255,255,.5)}\n\n/* manifesto */\n.mani{padding-block:110px 90px;display:grid;grid-template-columns:minmax(0,1.25fr) minmax(0,1fr);gap:72px;align-items:start}\n.mani h2{font-size:clamp(44px,5.6vw,82px);line-height:.9}\n.mani h2 em{font-style:normal;color:var(--c)}\n.mani .lead{font-size:21px;line-height:1.5;color:var(--ink);margin:0 0 22px}\n.mani p{margin:0 0 1em;color:var(--ink2)}\n\n/* faixa de dados */\n.facts{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));border-top:1px solid var(--line);border-bottom:1px solid var(--line)}\n.facts div{padding:22px 24px 22px 0}\n.facts div+div{border-left:1px solid var(--line);padding-left:24px}\n.facts dt{font-family:var(--d);font-size:12.5px;letter-spacing:2px;text-transform:uppercase;color:var(--mut)}\n.facts dd{margin:6px 0 0;font-family:var(--d);font-weight:700;font-size:24px;line-height:1.05;text-transform:uppercase}\n.facts dd small{display:block;font-family:var(--t);font-weight:400;font-size:14px;text-transform:none;color:var(--ink2);margin-top:4px}\n\n/* foto editorial */\n.ed{margin:90px 0 0;position:relative}\n.ed img{width:100%;aspect-ratio:21/9;object-fit:cover}\n.ed figcaption{display:flex;justify-content:space-between;gap:20px;font-size:14px;color:var(--mut);padding-top:12px}\n\n/* momentos */\n.mom{padding-block:110px 40px}\n.mom-h{display:flex;justify-content:space-between;align-items:flex-end;gap:30px;margin-bottom:40px;flex-wrap:wrap}\n.mom-h h2{font-size:clamp(38px,4.4vw,62px);line-height:.92}\n.mom-h p{margin:0;max-width:40ch;color:var(--ink2)}\n.mg{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:28px}\n.mg article img{width:100%;aspect-ratio:4/5;object-fit:cover}\n.mg .tm{display:flex;align-items:baseline;gap:12px;margin-top:18px}\n.mg .tm span{font-family:var(--d);font-weight:600;font-size:15px;color:var(--c);letter-spacing:1px}\n.mg h3{font-size:28px;line-height:1}\n.mg p{margin:8px 0 0;color:var(--ink2);font-size:16px}\n\n/* video */\n.vsec{margin-top:110px;background:var(--ink);color:#fff;padding-block:90px}\n.vsec .eyebrow{color:rgba(255,255,255,.6)}\n.vsec h2{font-size:clamp(36px,4vw,56px);line-height:.95;margin:10px 0 30px}\n.vbox{position:relative;aspect-ratio:16/9;background:#000;overflow:hidden}\n.vbox video{width:100%;height:100%;object-fit:cover}\n.vtabs{display:flex;gap:26px;margin-top:18px;font-size:15px}\n.vtabs button{color:rgba(255,255,255,.6);padding-bottom:6px;border-bottom:2px solid transparent}\n.vtabs button.on{color:#fff;border-color:var(--green)}\n\n/* galeria */\n.gal{padding-block:110px 40px}\n.gal h2{font-size:clamp(38px,4.4vw,62px);line-height:.92;margin:10px 0 34px}\n.gg{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));grid-auto-rows:150px;gap:12px}\n.gg button{overflow:hidden;position:relative;background:var(--paper)}\n.gg img{width:100%;height:100%;object-fit:cover;transition:transform .8s cubic-bezier(.2,.7,.2,1)}\n.gg button:hover img{transform:scale(1.04)}\n.gg button:nth-child(1){grid-column:span 4;grid-row:span 3}\n.gg button:nth-child(2){grid-column:span 2;grid-row:span 2}\n.gg button:nth-child(3){grid-column:span 2;grid-row:span 1}\n.gg button:nth-child(4){grid-column:span 3;grid-row:span 2}\n.gg button:nth-child(5){grid-column:span 3;grid-row:span 2}\n.gg button:nth-child(6){grid-column:span 2;grid-row:span 2}\n.gg button:nth-child(7){grid-column:span 2;grid-row:span 2}\n.gg button:nth-child(8){grid-column:span 2;grid-row:span 2}\n.gg figcaption{position:absolute;left:0;right:0;bottom:0;padding:30px 14px 10px;background:linear-gradient(transparent,rgba(9,22,40,.7));color:#fff;font-size:13px;text-align:left;opacity:0;transition:opacity .3s}\n.gg button:hover figcaption{opacity:1}\n\n/* localizacao */\n.loc{padding-block:110px;display:grid;grid-template-columns:minmax(0,1.3fr) minmax(0,1fr);gap:56px;align-items:start}\n.map{position:relative;aspect-ratio:4/3;overflow:hidden;background:#101d2e}\n.map img{position:absolute;max-width:none}\n.map .me{position:absolute;width:18px;height:18px;margin:-9px 0 0 -9px;border-radius:50%;background:var(--c);border:3px solid #fff;box-shadow:0 0 0 10px rgba(30,134,208,.28)}\n.map .near{position:absolute;width:10px;height:10px;margin:-5px 0 0 -5px;border-radius:50%;background:#fff;box-shadow:0 0 0 2px rgba(13,43,77,.5)}\n.map .near b{position:absolute;left:14px;top:-7px;white-space:nowrap;font-family:var(--d);font-size:13px;font-weight:600;color:#fff;text-shadow:0 1px 3px rgba(0,0,0,.8);text-transform:uppercase;letter-spacing:.5px}\n.loc h2{font-size:clamp(34px,3.6vw,50px);line-height:.95;margin:10px 0 14px}\n.loc p{margin:0 0 26px;color:var(--ink2)}\n.near-l{list-style:none;margin:0;padding:0;border-top:1px solid var(--line)}\n.near-l li{display:flex;align-items:center;gap:16px;padding:12px 0;border-bottom:1px solid var(--line)}\n.near-l img{width:84px;aspect-ratio:3/2;object-fit:cover}\n.near-l b{display:block;font-family:var(--d);font-size:20px;text-transform:uppercase;line-height:1.05}\n.near-l small{color:var(--mut);font-size:14px}\n\n/* agenda */\n.ag{background:var(--paper);padding-block:70px}\n.ag .wrap{display:flex;justify-content:space-between;align-items:center;gap:30px;flex-wrap:wrap}\n.ag h2{font-size:clamp(30px,3.2vw,44px);line-height:.95}\n.ag p{margin:8px 0 0;color:var(--ink2)}\n.cta{height:52px;padding:0 26px;border-radius:26px;background:var(--ink);color:#fff;font-family:var(--d);font-weight:700;font-size:17px;letter-spacing:1px;text-transform:uppercase;display:inline-flex;align-items:center;gap:10px}\n.cta svg{width:14px;height:14px}\n\n/* proximo */\n.nx{display:grid;grid-template-columns:1fr 1fr}\n.nx button{position:relative;height:300px;overflow:hidden;text-align:left;color:#fff}\n.nx img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;transition:transform .8s}\n.nx button:hover img{transform:scale(1.04)}\n.nx button::after{content:\"\";position:absolute;inset:0;background:linear-gradient(transparent 30%,rgba(9,22,40,.85))}\n.nx span{position:absolute;left:32px;right:32px;bottom:28px;z-index:1}\n.nx small{font-size:13px;letter-spacing:2px;text-transform:uppercase;font-family:var(--d);opacity:.85}\n.nx b{display:block;font-family:var(--d);font-size:clamp(28px,3vw,42px);text-transform:uppercase;line-height:1}\n.nx button+button span{text-align:right}\n\n.foot{background:var(--ink);color:rgba(255,255,255,.7);font-size:14px;padding-block:28px;border-top:3px solid var(--green)}\n\n/* lightbox */\n.lb{position:fixed;inset:0;z-index:100;background:rgba(7,16,28,.97);display:flex;align-items:center;justify-content:center}\n.lb img{max-width:min(1500px,92vw);max-height:82vh;object-fit:contain}\n.lb .c{position:absolute;left:0;right:0;bottom:max(20px,env(safe-area-inset-bottom,0px));text-align:center;color:rgba(255,255,255,.8);font-size:14px}\n.lb .a{position:absolute;top:50%;transform:translateY(-50%);width:54px;height:54px;border-radius:50%;background:rgba(255,255,255,.1);color:#fff;display:flex;align-items:center;justify-content:center}\n.lb .a.l{left:max(18px,env(safe-area-inset-left,0px))}.lb .a.r{right:max(18px,env(safe-area-inset-right,0px))}\n.lb .x{position:absolute;top:max(18px,env(safe-area-inset-top,0px));right:max(22px,env(safe-area-inset-right,0px));color:#fff;font-size:15px;border-bottom:1px solid rgba(255,255,255,.5)}\n.lb svg{width:18px;height:18px}\n\n.rv{opacity:0;transform:translateY(24px);transition:opacity .9s ease,transform .9s cubic-bezier(.2,.7,.2,1)}\n.rv.in{opacity:1;transform:none}\n\n@media (max-width:980px){\n  .site nav{display:none}\n  .mani,.loc{grid-template-columns:1fr;gap:28px}\n  .mani{padding-block:70px 60px}\n  .facts{grid-template-columns:1fr 1fr}\n  .facts div:nth-child(3){border-left:0;padding-left:0}\n  .facts div:nth-child(n+3){border-top:1px solid var(--line)}\n  .mg{grid-template-columns:1fr;gap:40px}\n  .mg article img{aspect-ratio:4/3}\n  .gg{grid-template-columns:1fr 1fr;grid-auto-rows:130px}\n  .gg button:nth-child(n){grid-column:span 1;grid-row:span 1}\n  .gg button:nth-child(1){grid-column:span 2;grid-row:span 2}\n  .gg button:nth-child(4){grid-column:span 2;grid-row:span 2}\n  .ed img{aspect-ratio:4/3}\n  .nx{grid-template-columns:1fr}\n  .nx button{height:220px}\n  .cover .sub{flex-direction:column;align-items:flex-start}\n  .mom,.gal,.loc{padding-block:70px 30px}\n  .vsec{margin-top:70px;padding-block:60px}\n}\n@media (max-width:560px){.wrap{padding-left:max(16px,env(safe-area-inset-left,0px));padding-right:max(16px,env(safe-area-inset-right,0px))}.facts dd{font-size:20px}}\n@media (prefers-reduced-motion:reduce){*{transition:none!important;animation:none!important}.rv{opacity:1;transform:none}}\n\n/* ===== mapa ===== */\n.top{position:relative;height:min(86vh,780px);min-height:520px;overflow:hidden;background:#0a1a2c;color:#fff}\n.top img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;animation:kb 20s ease-out both}\n.top::after{content:\"\";position:absolute;inset:0;background:linear-gradient(180deg,rgba(13,43,77,.25),rgba(13,43,77,.05) 35%,rgba(13,43,77,.82))}\n.top .wrap{position:relative;z-index:1;height:100%;display:flex;flex-direction:column;justify-content:flex-end;padding-block:0 56px}\n.top .loc0{position:absolute;top:28px;color:#fff;text-shadow:0 1px 4px rgba(0,0,0,.5);display:flex;align-items:center;gap:8px;font-family:var(--d);font-size:13px;letter-spacing:2.5px;text-transform:uppercase;opacity:.85}\n.top .loc0 i{width:7px;height:7px;border-radius:50%;background:#58B947}\n.eyebrow{font-family:var(--d);font-weight:600;font-size:14px;letter-spacing:2.8px;text-transform:uppercase}\n.top h1{color:#fff;font-size:clamp(64px,10vw,150px);line-height:.86;margin:12px 0 22px}\n.top h1 em{font-style:normal;color:#58B947}\n.top .row{display:flex;justify-content:space-between;align-items:flex-end;gap:24px}\n.top p{margin:0;max-width:420px;font-size:19px;line-height:1.5;color:rgba(255,255,255,.9)}\n.down{width:52px;height:52px;border-radius:50%;border:1px solid rgba(255,255,255,.6);display:flex;align-items:center;justify-content:center;color:#fff;flex:none}\n.down svg{width:16px;height:16px}\n.trilhas{padding-block:84px 30px}\n.trilhas .eyebrow{color:var(--mut)}\n.trilhas h2{font-size:clamp(40px,5vw,68px);line-height:.92;margin:10px 0 14px}\n.trilhas>p{margin:0 0 36px;color:var(--ink2);max-width:46ch}\n.tg{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));border-top:1px solid #CFD5DC;border-bottom:1px solid #CFD5DC}\n.tg button{text-align:left;padding:24px 22px 22px;border-left:1px solid #CFD5DC;position:relative;transition:background .25s}\n.tg button:first-child{border-left:0;padding-left:0}\n.tg button:hover{background:rgba(13,43,77,.03)}\n.tg button.on::before{content:\"\";position:absolute;left:0;right:0;top:-1px;height:3px;background:var(--c,var(--ink))}\n.tg b{display:flex;align-items:center;gap:9px;font-family:var(--d);font-weight:700;font-size:clamp(22px,2.2vw,30px);text-transform:uppercase;line-height:1}\n.tg b i{width:9px;height:9px;border-radius:50%;background:var(--c)}\n.tg span{display:block;font-size:14px;color:var(--mut);margin-top:6px}\n.intro{display:none;padding-block:64px 28px;display:grid;grid-template-columns:minmax(0,1.1fr) minmax(0,1fr);gap:48px;align-items:end}\nh1,h2,h3{font-family:var(--d);font-weight:700;letter-spacing:-.2px;margin:0;color:var(--ink);text-transform:uppercase}\n.intro h1{font-size:clamp(44px,6vw,80px);line-height:.92}\n.intro p{margin:0;color:var(--ink2);font-size:18px;max-width:46ch}\n.tabs{display:none;gap:28px;border-bottom:1px solid var(--line);margin-bottom:24px;overflow-x:auto}\n.tabs button{position:relative;padding:12px 0 14px;font-size:16px;color:var(--mut);white-space:nowrap;display:flex;align-items:center;gap:8px}\n.tabs button i{width:8px;height:8px;border-radius:50%;background:var(--c)}\n.tabs button.on{color:var(--ink);font-weight:600}\n.tabs button.on::after{content:\"\";position:absolute;left:0;right:0;bottom:-1px;height:2px;background:var(--ink)}\n.explore{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:40px;padding-block:36px 80px}\n.stage{position:relative;border-radius:2px;overflow:hidden;background:#0a1a2c;aspect-ratio:2600/1213;max-width:100%}\n.layer{position:absolute;inset:0;transform-origin:0 0;transition:transform .9s cubic-bezier(.65,0,.2,1)}\n.layer img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}\n.pin{position:absolute;width:0;height:0;z-index:2;transition:opacity .35s}\n.pin .dot{position:absolute;left:-9px;top:-9px;width:18px;height:18px;border-radius:50%;background:var(--c);border:3px solid #fff;box-shadow:0 3px 10px rgba(0,0,0,.4);transition:transform .25s}\n.pin.obra .dot{background:#fff;box-shadow:inset 0 0 0 4px var(--c),0 3px 10px rgba(0,0,0,.4)}\n.pin .pl{position:absolute;left:0;bottom:16px;transform:translateX(-50%);white-space:nowrap;background:#fff;color:var(--ink);font-family:var(--d);font-weight:600;font-size:15px;padding:4px 10px;border-radius:3px;box-shadow:0 4px 14px rgba(0,0,0,.25);opacity:0;pointer-events:none;transition:opacity .2s}\n.pin:hover .pl,.pin.hl .pl{opacity:1}\n.pin:hover .dot,.pin.hl .dot{transform:scale(1.35)}\n.pin:hover,.pin.hl{z-index:5}\n.pin.dim{opacity:.12;pointer-events:none}\n.leg{position:absolute;left:16px;bottom:14px;display:flex;gap:16px;flex-wrap:wrap;font-size:13px;color:#fff;text-shadow:0 1px 3px rgba(0,0,0,.6)}\n.leg span{display:inline-flex;align-items:center;gap:6px}\n.leg i{width:9px;height:9px;border-radius:50%;background:var(--c);border:2px solid #fff}\n.leg i.o{background:#fff;box-shadow:inset 0 0 0 2px #888}\n.index{min-width:0}\n.index h4{margin:22px 0 6px;font-family:var(--d);font-weight:700;font-size:19px;display:flex;align-items:center;gap:8px}\n.index h4:first-child{margin-top:0}\n.index h4 i{width:9px;height:9px;border-radius:50%;background:var(--c)}\n.index ul{list-style:none;margin:0;padding:0}\n.index li button{width:100%;display:flex;justify-content:space-between;gap:10px;align-items:baseline;text-align:left;padding:7px 0;border-bottom:1px solid var(--line);font-size:15.5px;color:var(--ink2);transition:color .2s,padding .25s}\n.index li button:hover,.index li button.hl{color:var(--ink);padding-left:6px}\n.index small{font-size:12.5px;color:var(--obra);white-space:nowrap}\n.cheg{border-top:1px solid var(--line);padding-block:40px 90px;display:grid;grid-template-columns:240px 1fr;gap:40px}\n.cheg h3{font-size:26px;line-height:1}\n.cheg p{margin:8px 0 0;color:var(--mut);font-size:15px}\n.cg{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px}\n.cg img{aspect-ratio:3/2;width:100%;object-fit:cover;border-radius:4px}\n.cg b{display:block;font-family:var(--d);font-size:19px;margin-top:10px;line-height:1.1}\n.cg span{font-size:14px;color:var(--mut)}\n\n\n\n.near-l li{cursor:pointer}.near-l li:hover b{color:var(--c)}\n.news{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:32px}\n.news article{border-top:2px solid var(--ink);padding-top:16px}\n.news .src{font-size:13.5px;color:var(--mut)}\n.news h3{font-size:23px;line-height:1.1;margin:8px 0 10px}\n.news p{margin:0;font-size:15px;color:var(--ink2);line-height:1.5}\n.nsec{padding-block:30px 100px}\n.nsec h2{font-size:clamp(38px,4.4vw,62px);line-height:.92;margin:10px 0 34px}\n.gg.c1{grid-template-columns:1fr;grid-auto-rows:auto}.gg.c1 button{aspect-ratio:16/8}\n.gg.c2{grid-template-columns:1fr 1fr;grid-auto-rows:340px}\n.gg.c3{grid-template-columns:2fr 1fr;grid-auto-rows:220px}\n.gg.c4{grid-template-columns:2fr 1fr;grid-auto-rows:150px}\n.gg.c1 button:nth-child(n),.gg.c2 button:nth-child(n),.gg.c3 button:nth-child(n),.gg.c4 button:nth-child(n){grid-column:auto;grid-row:auto}\n.gg.c3 button:first-child{grid-row:span 2!important}\n.gg.c4 button:first-child{grid-row:span 3!important}\n.nota{background:#0a2240;color:#fff;font-size:14px}\n.nota .wrap{display:flex;gap:14px;align-items:center;min-height:42px;flex-wrap:wrap;padding-block:6px}\n.nota b{color:var(--green)}.nota span{opacity:.75}\n@media (max-width:980px){\n  .tg{grid-template-columns:1fr 1fr}.tg button:nth-child(3){border-left:0;padding-left:0}.tg button:nth-child(n+3){border-top:1px solid #CFD5DC}\n  .explore{grid-template-columns:1fr}\n  .stage{aspect-ratio:auto;height:62vh}.layer{width:auto;aspect-ratio:2600/1213;height:100%;right:auto}\n  .cheg{grid-template-columns:1fr}.cg,.news{grid-template-columns:1fr}\n  .gg.c2,.gg.c3,.gg.c4{grid-template-columns:1fr 1fr;grid-auto-rows:150px}\n  .gg.c3 button:first-child,.gg.c4 button:first-child{grid-column:span 2!important;grid-row:span 2!important}\n  .nota span{display:none}\n}\n.cover h1,.cover .trail{color:#fff}\n\n@media (max-width:900px){.cover{height:calc(100svh - 92px)}.top{height:calc(100svh - 92px)}}\n.lb{z-index:5000}\n.site,.nota,.foot{display:none}\n\n.hero2{position:relative;height:min(52vh,460px);min-height:300px;overflow:hidden;background:#0a1a2c;color:#fff}\n.hero2 img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}\n.hero2::after{content:\"\";position:absolute;inset:0;background:linear-gradient(180deg,rgba(13,43,77,.2),rgba(13,43,77,.75))}\n.hero2 .wrap{position:absolute;inset:auto 0 36px 0;z-index:1}\n.hero2 h1{color:#fff;font-size:clamp(40px,6vw,76px);line-height:.9;margin:8px 0 8px}\n.hero2 p{margin:0;font-size:17px;color:rgba(255,255,255,.9)}\n.bar2{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap;padding-block:22px 10px;position:sticky;top:136px;z-index:20;background:var(--bg)}\n.seg{display:flex;gap:6px;flex-wrap:wrap}\n.seg button{height:38px;padding:0 14px;border-radius:19px;border:1px solid var(--line);font-size:14.5px;color:var(--ink2);display:inline-flex;align-items:center;gap:8px;background:#fff}\n.seg button i{width:8px;height:8px;border-radius:50%;background:var(--c)}\n.seg button small{font-size:12px;color:var(--mut)}\n.seg button.on{background:var(--ink);color:#fff;border-color:var(--ink)}.seg button.on small{color:rgba(255,255,255,.7)}\n.view{display:inline-flex;background:#fff;border:1px solid var(--line);border-radius:19px;padding:3px}\n.view button{height:30px;padding:0 14px;border-radius:15px;font-size:14px;color:var(--mut)}\n.view button.on{background:var(--ink);color:#fff}\n.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:22px 20px;padding-block:14px 60px}\n.tile{text-align:left;display:flex;flex-direction:column;gap:12px;color:var(--ink)}\n.tile .im{position:relative;display:block;aspect-ratio:4/3;border-radius:10px;overflow:hidden;background:#dfe3e8}\n.tile img{width:100%;height:100%;object-fit:cover;transition:transform .7s cubic-bezier(.2,.7,.2,1)}\n.tile:hover img{transform:scale(1.05)}\n.tile em{position:absolute;left:10px;top:10px;font-style:normal;font-family:var(--d);font-size:11.5px;letter-spacing:1px;text-transform:uppercase;background:#fff;color:var(--ink);padding:3px 8px;border-radius:3px}\n.tile .tx small{display:flex;align-items:center;gap:6px;font-size:12.5px;color:var(--mut);letter-spacing:.3px}\n.tile .tx small i{width:7px;height:7px;border-radius:50%;background:var(--c)}\n.tile .tx b{display:block;font-family:var(--d);font-weight:700;font-size:24px;line-height:1;text-transform:uppercase;margin:4px 0 4px}\n.tile .tx span{display:block;font-size:14.5px;color:var(--ink2);line-height:1.45;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}\n.pop{position:absolute;left:16px;bottom:16px;z-index:6;display:flex;gap:12px;align-items:center;background:#fff;border-radius:10px;padding:10px;box-shadow:0 10px 30px rgba(0,0,0,.3);max-width:min(380px,calc(100% - 32px))}\n.pop img{width:96px;height:72px;object-fit:cover;border-radius:6px;flex:none}\n.pop small{display:flex;align-items:center;gap:6px;font-size:12px;color:var(--mut)}.pop small i{width:7px;height:7px;border-radius:50%;background:var(--c)}\n.pop b{display:block;font-family:var(--d);font-size:19px;text-transform:uppercase;line-height:1.05;margin:2px 0 4px}\n.pop .go2{font-size:14px;font-weight:600;color:var(--ink);border-bottom:1.5px solid var(--ink)}\n#mapaV .stage{margin-top:14px;aspect-ratio:16/9;cursor:default}\n#mapaV .stage .leg{bottom:auto;top:12px}\n.cheg2{padding-block:10px 80px}\n.cheg2 .cg{margin-top:12px}\n@media (max-width:980px){.grid{grid-template-columns:1fr 1fr;gap:16px 12px}.tile .tx b{font-size:19px}.tile .tx span{display:none}#mapaV .stage{aspect-ratio:auto;height:70vh}}\n@media (max-width:560px){.grid{grid-template-columns:1fr}.hero2{height:46vh}}\n\n#mapaV .pin .pl{opacity:1;background:#fff;color:var(--ink);text-shadow:none;padding:3px 8px;border-radius:3px;font-size:12px;bottom:13px;box-shadow:0 2px 8px rgba(0,0,0,.25)}#mapaV .pin .pl::after{display:none}#mapaV .pin.dim .pl{opacity:0}#mapaV .pin.hl .pl{background:var(--ink);color:#fff}\n";

