  const xh = $('#xh'), nome = s.v && s.v[0];
  if(!xh || !nome || matchMedia('(prefers-reduced-motion: reduce)').matches || (navigator.connection && navigator.connection.saveData)) return;
  const v = document.createElement('video');
  v.className = 'xv'; v.muted = true; v.loop = true; v.playsInline = true; v.preload = 'auto';
  v.setAttribute('muted', ''); v.setAttribute('playsinline', ''); v.setAttribute('aria-hidden', 'true');
