if(!customElements.get('pnmt-espacos')) customElements.define('pnmt-espacos', PnmtEspacos);

function take(){
  const main = document.getElementById('main'); if(!main) return;
  const r = (location.hash.slice(1) || 'inicio').split('?')[0];
  let id = null;
  if(r === 'espacos') id = '';
  else { const m = /^espaco\/([a-z0-9-]+)$/.exec(r); if(m && BY[m[1]]) id = BY[m[1]]; }
  let el = main.querySelector(':scope > pnmt-espacos');
  if(id === null){ if(el) el.remove(); return; }
  if(el && el.dataset.view !== id){ el.remove(); el = null; }
  if(!el){ el = document.createElement('pnmt-espacos'); el.dataset.view = id; main.prepend(el); window.scrollTo(0,0); }
  main.querySelectorAll('pnmt-explore, pnmt-mapa-real').forEach(x => x.remove());
  [...main.children].forEach(c => { if(c !== el && !c.hidden) c.hidden = true; });
}
function start(){
  const main = document.getElementById('main'); if(!main) return;
  take();
  new MutationObserver(take).observe(main, {childList:true});
  window.addEventListener('hashchange', () => queueMicrotask(take));
}
if(document.readyState === 'loading') document.addEventListener('DOMContentLoaded', start, {once:true}); else start();
